import{_ as p,a0 as a,w as s,s as u,ao as o,I as e,x as l,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"我如何通過開源來發展我的產品經理職業 | LCTT x X-CMD","titleTemplate":false,"description":"我如何通過開源來發展我的產品經理職業 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我如何通過開源來發展我的產品經理職業 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我如何通過開源來發展我的產品經理職業 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220427 How I grew my product management career with open source","title":"我如何通過開源來發展我的產品經理職業","tag":"202205","desc":""},"relativePath":"202205/20220427 How I grew my product management career with open source.md","filePath":"[post].md"}'),d={name:"202205/20220427 How I grew my product management career with open source.md"};function m(f,t,T,g,b,x){const r=a("Link");return s(),u("div",null,[t[29]||(t[29]=o('<h1 id="我如何通過開源來發展我的產品經理職業" tabindex="-1">我如何通過開源來發展我的產品經理職業 <a class="header-anchor" href="#我如何通過開源來發展我的產品經理職業" aria-label="Permalink to “我如何通過開源來發展我的產品經理職業”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/08/112446zy420r4zutdlu0ol.jpg" alt=""></p><blockquote><p>毫不誇張地説，在開源方面獲得的經驗，幫助我在產品管理領域創造了一條成功的職業道路。</p></blockquote><p>我是一個充滿好奇心的人，我喜歡探索科技行業的許多領域，從視覺設計、編程到產品管理。我也被開放源碼的理念所吸引。因此，我很高興與大家分享我作為一個產品經理（PM），是如何利用開源來建立我的職業生涯的。我相信我的經驗可以幫助其他對產品管理感興趣的人。</p><h3 id="什麼是開源軟件" tabindex="-1">什麼是開源軟件 <a class="header-anchor" href="#什麼是開源軟件" aria-label="Permalink to “什麼是開源軟件”">​</a></h3>',5)),e("p",null,[t[1]||(t[1]=l("簡單地説，開源軟件是開放源代碼的軟件，這意味着任何人都可以檢查、修改、增強和分享它的源代碼。我們發表過一篇詳細、",-1)),i(r,{href:"https://linux.cn/article-8624-1.html"},{default:n(()=>[...t[0]||(t[0]=[l("全面的文章",-1)])]),_:1}),t[2]||(t[2]=l(" 來幫助你瞭解什麼是開源。",-1))]),t[30]||(t[30]=o('<p>我最早知道開源是很久以前了，那時，我還是一名剛入行不久的視覺設計師。我很想知道開源是什麼，也很想知道如何成為它的一部分。在這種好奇心的驅使下，我接觸到了一些有經驗的開源貢獻者和倡導者。雖然我當時沒有做出貢獻，但是他們讓我知道了什麼是社區，這對我下定決心開始貢獻有很大幫助。</p><h3 id="如何上手產品管理" tabindex="-1">如何上手產品管理 <a class="header-anchor" href="#如何上手產品管理" aria-label="Permalink to “如何上手產品管理”">​</a></h3><p>產品管理工作貌似是一件很難上手的事情，感覺必須要戴上拳擊手套，經過一番搏鬥，才能強行進入這一行。然而，我從其他產品經理那裏聽説，與編寫/調試代碼塊，或使用像素點生成複雜的產品設計線框相比，產品管理工作其實是更好上手的。</p><p>雖然我們的經歷和經驗各不相同，但是有一點可以確定：成為產品經理的道路往往是漫長而不可預知的。隨着就業競爭的不斷加劇，獲得一個初級產品經理的職位可能會很困難。應聘者通常被要求有 2 到 3 年的經驗才能加入產品團隊。這時你可能會問：“我應該如何獲得這些經驗呢？”</p><p>來看看下面這四個策略吧，它們或許能夠將你的職業生涯轉向到產品管理：</p><ol><li>在一個大型組織的內部轉崗。這可能需要你的經理為你説一些好話，比如，説你很適合在公司內部轉崗等。你必須有證據表明你掌握了該崗位的技能。這通常被認為是獲得產品管理經驗的最快</li><li>擔任大型組織的初級產品經理角色。通過它獲得實習機會，或者加入一個需要初級產品經理的關副產品管理項目，這些都很常見。</li><li>你也可以嘗試通過加入創業公司來上手產品管理工作。</li><li>你還可以啓動一個自己的副業項目來上手產品管理工作。</li></ol>',6)),e("p",null,[t[4]||(t[4]=l("缺乏實踐經驗，就很難成為產品經理。正如開源產品經理 ",-1)),i(r,{href:"https://twitter.com/hellodavidryan"},{default:n(()=>[...t[3]||(t[3]=[l("David Ryan",-1)])]),_:1}),t[5]||(t[5]=l(" 所説，“有一條獲得實際的產品管理經驗的途徑，它既未被人充分利用，也很少有人意識到並利用它們”。",-1))]),t[31]||(t[31]=e("p",null,"這條途徑是什麼？",-1)),t[32]||(t[32]=e("h3",{id:"答案就是開源",tabindex:"-1"},[l("答案就是開源 "),e("a",{class:"header-anchor",href:"#答案就是開源","aria-label":"Permalink to “答案就是開源”"},"​")],-1)),t[33]||(t[33]=e("p",null,"一個開放源碼項目要想成功，需要的不僅僅是代碼。它還包括項目戰略、用户研究，以及將戰略與日常工作聯繫起來。這些都是產品經理應該積極參加的活動。但是，在產品管理這一行裏，有多少職責會分配給一個新手產品經理呢？",-1)),e("p",null,[i(r,{href:"https://twitter.com/susanavlopes"},{default:n(()=>[...t[6]||(t[6]=[l("Susana Videira Lopes",-1)])]),_:1}),t[7]||(t[7]=l(" 在她的一篇文章中指出，“獲得一個入門級的產品角色，本質就是以一種建立你的信心的方式，讓你加入到至產品管理這一行，同時儘早為組織提供價值”。",-1))]),t[34]||(t[34]=o('<p>一個入門級的產品經理該如何參與開源項目，併為它提供價值呢？</p><p><strong>答案很簡單：多問問題</strong></p><p>這裏有一些你可以問的問題：</p><ul><li>正在探索的是什麼問題/機會？</li><li>如何制定解決方案來解決這個問題？</li><li>用什麼標準來確定項目是否成功？</li><li>這個解決方案的服務對象是誰？</li><li>他們是如何被告知這個解決方案的？</li><li>該解決方案如何與當前和更廣泛的生態系統相適應？</li><li>項目的文件是在哪裏維護的？</li><li>項目維護者是否瞭解<ruby>無障礙<rt>accessibility</rt></ruby>要求？它們是否被滿足？</li></ul><p>既然你已經獲得了產品經理的所需技能，為何不應用它們呢？結合所學，表達出你深思熟慮的問題，並邀請你的團隊來評估吧！你的團隊可以選擇那些能引起開發者和社區共鳴的問題，並優先考慮其中最重要的。</p><p>這些問題可以幫助你建立用户角色、用户旅程圖、精益畫布，以及更多。這種經驗對發展職業潛力有很大的幫助。</p><h3 id="我在-openunited-的經歷" tabindex="-1">我在 OpenUnited 的經歷 <a class="header-anchor" href="#我在-openunited-的經歷" aria-label="Permalink to “我在 OpenUnited 的經歷”">​</a></h3>',7)),e("p",null,[i(r,{href:"https://openunited.com"},{default:n(()=>[...t[8]||(t[8]=[l("OpenUnited",-1)])]),_:1}),t[9]||(t[9]=l(" 是一個以獨特方式連接數字人才和工作的平台。我們與貢獻者合作，幫助他們投入到高質量的開源產品，從而證明自身的特定技能。一旦他們的工作得到驗證，這些有才華的貢獻者就有資格在公司裏從事有償工作。",-1))]),t[35]||(t[35]=o('<p>OpenUnited 是一個開源平台，為各類貢獻者（包括產品經理、開發人員、設計師、商業分析師和其他人）提供服務。它致力於幫助貢獻者提高技能，併為他們提供長期的高質量付費工作來源。</p><p>Miro 公司的高級產品經理 Farbod Saraf 讓我加入他與合作伙伴創建的一個平台。我加入了這個項目，並瞭解瞭如何對 OpenUnited 做出貢獻。我還了解了其他可以幫助我在產品管理生涯中成長的項目，並做出了我的第一次貢獻。這是一次很好的經歷，因為我可以迅速地開始投入到產品的某些部分，以改善平台上其他用户的體驗。在我為項目做貢獻的時候，我的導師 Farbod 隨時為我提供任何需要的幫助，使我的工作更加輕鬆。</p><p>你對開源項目所做的一切貢獻，都會成為你成長為產品經理過程中的有力的公共記錄。對於任何想通過開源上手產品管理的人，我都強烈推薦 OpenUnited 平台。</p><h3 id="如何找到開源項目" tabindex="-1">如何找到開源項目 <a class="header-anchor" href="#如何找到開源項目" aria-label="Permalink to “如何找到開源項目”">​</a></h3><p>許多人認為，貢獻開源只適合於開發人員，因為他們覺得找到一個可以舒適地貢獻的開源項目是很難的。</p><p>即使作為一個初出茅廬的產品經理，也有好幾種方法可以找到適合貢獻的開源項目。這裏列出了一些：</p><ul><li>在產品經理社區中發言，如 Mind The Product 和 Product School。</li><li>參加當地的聚會和開源會議，如非洲開源社區節，以此來與開源項目的創建者和維護者保持聯繫。</li><li>與在 GitLab 或 Mozilla 等大型開源公司工作的產品經理接觸。他們可能會把你推薦到需要你的技能和貢獻的開源項目中。</li><li>聯繫開源公司的開源倡導者和開發者關係團隊，讓他們推薦一些適合入門級產品經理貢獻的開源項目。</li><li>尋找 AngelList 上的開源公司或 Product Hunt 上流行的開源產品。這些都是你可以找到適合貢獻的開源產品的好地方。</li></ul><h3 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h3>',8)),e("p",null,[i(r,{href:"https://stars.github.com/profiles/ruth-ikegah/"},{default:n(()=>[...t[10]||(t[10]=[l("Ruth Ikegah",-1)])]),_:1}),t[12]||(t[12]=l(" 是我的一個重要靈感來源，她 ",-1)),i(r,{href:"https://ruthikegah.xyz/a-beginners-guide-to-open-source"},{default:n(()=>[...t[11]||(t[11]=[l("為開源新手寫了一篇文章",-1)])]),_:1}),t[13]||(t[13]=l("。她的文章給出了一些提示，在你開始為開源做貢獻時，可能需要考慮一下它們。",-1))]),t[36]||(t[36]=e("p",null,"在加入和貢獻項目、社區或組織之前，對它們做一些研究，並提出自己的問題。當你最終決定加入社區時，試着積極地介紹自己，並説明你可以在哪些方面提供幫助。",-1)),t[37]||(t[37]=e("p",null,"當然，開源不僅僅是你職業生涯的一個墊腳石。它本身就是一個平台，而且它需要優秀的產品經理。參與進來吧！一方面，你能為社區做出貢獻；另一方面，它也能幫助你磨練自己的技能。",-1)),t[38]||(t[38]=e("hr",null,null,-1)),e("p",null,[t[15]||(t[15]=l("via: ",-1)),i(r,{href:"https://opensource.com/article/22/4/product-management-open-source"},{default:n(()=>[...t[14]||(t[14]=[l("https://opensource.com/article/22/4/product-management-open-source",-1)])]),_:1})]),e("p",null,[t[20]||(t[20]=l("作者：",-1)),i(r,{href:"https://opensource.com/users/shebuel"},{default:n(()=>[...t[16]||(t[16]=[l("Shebuel Inyang",-1)])]),_:1}),t[21]||(t[21]=l(" 選題：",-1)),i(r,{href:"https://github.com/lkxed"},{default:n(()=>[...t[17]||(t[17]=[l("lkxed",-1)])]),_:1}),t[22]||(t[22]=l(" 譯者：",-1)),i(r,{href:"https://github.com/lkxed"},{default:n(()=>[...t[18]||(t[18]=[l("lkxed",-1)])]),_:1}),t[23]||(t[23]=l(" 校對：",-1)),i(r,{href:"https://github.com/wxy"},{default:n(()=>[...t[19]||(t[19]=[l("wxy",-1)])]),_:1})]),e("p",null,[t[26]||(t[26]=l("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[24]||(t[24]=[l("LCTT",-1)])]),_:1}),t[27]||(t[27]=l(" 原創編譯，",-1)),i(r,{href:"https://linux.cn/"},{default:n(()=>[...t[25]||(t[25]=[l("Linux中國",-1)])]),_:1}),t[28]||(t[28]=l(" 榮譽推出",-1))])])}const w=p(d,[["render",m]]);export{k as __pageData,w as default};
